import {ThreatField,HOME_ORIGINS} from './automata.mjs';
import {TYPES,ORDER,FORMS,INCIDENTS,evaluatePolicy} from './catalog.mjs';
import {makeInspection,inspectionVerdict,inspectionReason,THREATS,REVIEW_SECONDS} from './threats.mjs';
export {TYPES,ORDER,FORMS,INCIDENTS} from './catalog.mjs';
export class Shift{
 constructor({director=null}={}){this.director=director;this.time=0;this.running=false;this.started=false;this.done=false;this.data=100;this.trust=100;this.exposedRecords=0;this.alteredRecords=0;this.allowed=0;this.stopped=0;this.mistakes=0;this.repaired=0;this.serial=0;this.quarantineUses=0;this.requests=[];this.threatFields=new Map();this.effects=[];this.record=[];this.lastLog='当直開始待ち。6項目の証拠を照合し、権限・送信条件・処理量を判断してください。';this.zones=Object.fromEntries(ORDER.map(k=>[k,{fixed:false,repairEnd:0,quarantineUntil:0,attacks:0,defended:0,correct:0,missed:0}]));}
 start(){if(this.started)return;this.started=true;this.running=true;this.spawn();this.lastLog='当直開始。最初の通信が届きました。検査所見と通過条件を照合してください。';}
 spawn(){if(this.serial>=FORMS.length)return;let choice=null;try{choice=this.director?.select(this);}catch{}if(choice?.id===null){this.serial++;this.lastLog='防御状態に合う通信候補がなく、この投入枠は待機。';return;}const template=INCIDENTS.find(r=>r.id===choice?.id)||INCIDENTS[this.serial];const {type,a,b}=template,valid=evaluatePolicy(template,TYPES);const r={id:++this.serial,type,valid,a,b,templateId:template.id,enemySource:choice?.source==='decisions'?'decisions':'local',enemyReason:typeof choice?.reason==='string'?choice.reason:'固定順の通信。',at:this.time,deadline:Math.min(120,this.time+REVIEW_SECONDS),status:'pending'};r.inspection=makeInspection(r,r.id-1);r.valid=expectedVerdict(r);this.requests.push(r);this.effects.push({type,kind:'arrival',at:this.time,id:r.id});if(!r.valid&&this.zones[type].fixed){r.status='auto';this.stopped++;this.zones[type].defended++;this.effects.push({type,kind:'wall',at:this.time,id:r.id});this.lastLog=TYPES[type].name+'：修正済みの防壁が'+threatName(r)+'の模擬通信を自動拒否。';}else this.lastLog=TYPES[type].name+'に新しい通信。伝票 #'+String(r.id).padStart(3,'0')+' を審査。';}
 decide(id,allow,timeout=false){const r=this.requests.find(x=>x.id===id);if(!this.running||!r||r.status!=='pending')return false;const zone=this.zones[r.type];r.valid=expectedVerdict(r);r.status=timeout?'timeout':allow?'allow':'deny';r.decisionAt=this.time;r.correct=allow===r.valid;if(allow){this.allowed++;if(r.valid){zone.correct++;this.effects.push({type:r.type,kind:'good',at:this.time,id:r.id});this.lastLog='許可：正常なデータが申請された宛先へ届き、病院業務を支えました。';}else{this.mistakes++;zone.missed++;zone.attacks++;this.threatFields.set(r.id,new ThreatField(r.type,48,60,HOME_ORIGINS[r.type]));applyRecordDamage(this,r,r.type==='flood'?3:6);this.trust=Math.max(0,this.trust-(r.type==='flood'?5:0));this.effects.push({type:r.type,kind:'attack',at:this.time,id:r.id});this.lastLog=(timeout?'未審査のまま通過。':'誤って許可。')+threatName(r)+'が盤面に模擬侵入。模擬カルテの'+impactLabel(r)+'が増加。根本修正で拡大を止められます。';}}else{this.stopped++;if(r.valid){this.mistakes++;this.trust=Math.max(0,this.trust-8);this.effects.push({type:r.type,kind:'falseblock',at:this.time,id:r.id});this.lastLog='正常な通信を遮断。必要な検査結果が届かず、模擬予約8件を延期。';}else{zone.correct++;this.effects.push({type:r.type,kind:'stop',at:this.time,id:r.id});this.lastLog='遮断：この伝票の攻撃の芽を消去。抜け道は残ります。';}}this.record.push(r);return true;}
 repair(type){const z=this.zones[type];if(!this.running||!z||z.fixed||z.repairEnd||ORDER.some(k=>this.zones[k].repairEnd))return false;z.repairEnd=this.time+10;this.lastLog=TYPES[type].name+'を修正中。10秒後に防壁ができます。その間も伝票は届きます。';return true;}
 quarantine(type){const z=this.zones[type];if(!this.running||!z||z.fixed||z.quarantineUntil>this.time||this.quarantineUses>=2)return false;z.quarantineUntil=this.time+8;this.quarantineUses++;this.trust=Math.max(0,this.trust-4);this.lastLog=TYPES[type].name+'を8秒隔離。侵食と審査期限を一時停止。業務の一部停止により模擬予約4件を延期。';return true;}
 advance(dt){if(!this.running||dt<=0)return;const end=Math.min(120,this.time+dt);while(this.time<end){const prev=this.time;this.time=Math.min(end,this.time+.1);for(const r of this.pending()){const z=this.zones[r.type];if(z.quarantineUntil>prev)r.deadline+=Math.max(0,Math.min(this.time,z.quarantineUntil)-prev);}for(const type of ORDER){const z=this.zones[type];if(z.repairEnd&&this.time>=z.repairEnd){z.fixed=true;z.repairEnd=0;z.attacks=0;for(const field of this.threatFields.values())if(field.type===type)field.clear();this.repaired++;this.effects.push({type,kind:'wall',at:this.time,id:0});this.lastLog=TYPES[type].name+'：根本修正完了。侵食が止まり、防壁ができました。既存のカルテ閲覧不能・漏えい・改変と予約延期は残ります。';}}for(const field of this.threatFields.values()){const z=this.zones[field.type];if(!z.fixed&&z.quarantineUntil<=prev)field.advance(this.time-prev);}while(this.serial<FORMS.length&&this.time>=this.serial*7)this.spawn();for(const r of this.requests){if(r.status==='pending'&&this.time>=r.deadline)this.decide(r.id,true,true);}if(Math.floor(prev/4)<Math.floor(this.time/4)){for(const r of this.requests){const z=this.zones[r.type];if(this.threatFields.has(r.id)&&!z.fixed&&z.quarantineUntil<=this.time){applyRecordDamage(this,r,1);if(r.type==='flood')this.trust=Math.max(0,this.trust-1);}}}this.effects=this.effects.filter(e=>this.time-e.at<24);}if(this.time>=120){this.running=false;this.done=true;this.lastLog='当直終了。判断の結果を報告書にまとめました。';}}
 // Hospital counters are a game model: 100 synthetic records and 100 appointments.
 // Availability, confidentiality, integrity, and postponed work accumulate independently.
 // Blocking further damage never restores prior losses; none are historical totals.
 get unavailableRecords(){return 100-this.data;}
 get postponedAppointments(){return 100-this.trust;}
 pending(type){return this.requests.filter(r=>r.status==='pending'&&(!type||r.type===type));}
}
// B3/S23: normal service activity is an actual cellular automaton.
export function lifeStep(cells,w,h){const next=new Set();for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if((dx||dy)&&cells.has((y+dy)*w+x+dx))n++;const key=y*w+x;if(n===3||(n===2&&cells.has(key)))next.add(key);}return next;}
// Verdict and explanation use the same policy; the stored valid bit is not the answer key.
function threatName(r){return THREATS.find(t=>t.id===r.inspection?.patternId)?.name||TYPES[r.type].label;}
function impactKind(r){return THREATS.find(t=>t.id===r.inspection?.patternId)?.impactKind||'availability';}
function impactLabel(r){return {availability:'閲覧不能',confidentiality:'漏えい',integrity:'改変'}[impactKind(r)];}
function applyRecordDamage(shift,r,amount){const kind=impactKind(r);if(kind==='confidentiality')shift.exposedRecords=Math.min(100,shift.exposedRecords+amount);else if(kind==='integrity')shift.alteredRecords=Math.min(100,shift.alteredRecords+amount);else shift.data=Math.max(0,shift.data-amount);}
export function expectedVerdict(r){return r.inspection?inspectionVerdict(r.inspection):evaluatePolicy(r,TYPES);}
export function verdictReason(r){if(r.inspection)return inspectionReason(r.inspection);const ok=expectedVerdict(r);if(r.type==='auth')return ok?'本人と鍵の送信先が一致しています。':'本人と鍵の送信先が一致していません。別人へ鍵を渡すため拒否します。';if(r.type==='share')return ok?'持ち主と閲覧者が一致しています。':'閲覧者が持ち主と異なります。このモックの条件では共有権限がありません。';if(r.type==='flood')return ok?'毎秒'+r.b+'件で上限'+TYPES.flood.limit+'件以内です。':'毎秒'+r.b+'件は上限'+TYPES.flood.limit+'件を超えます。';return ok?(r.a===TYPES.exfil.publicValue?TYPES.exfil.publicValue+'なので外部への送信も許可します。':'社内資料を'+TYPES.exfil.internalValue+'へ送るため許可します。'):'社内資料を外部へ送ろうとしています。持ち出しを防ぐため拒否します。';}
